/**
 * Skill Template Workflow Modules
 *
 * This file is generated by splitting the legacy monolithic
 * templates file into workflow-focused modules.
 */
import type { SkillTemplate, CommandTemplate } from '../types.js';
import { getApplyInstructions } from './apply-change.js';
import { STORE_SELECTION_GUIDANCE } from './store-selection.js';
import { PROJECT_ROOT_GUARD } from './project-root.js';

const APPLY_ONE_CHANGE = getApplyInstructions()
  .replaceAll('`/opsx:apply add-auth`', '`the current batch entry`')
  .replaceAll('`/opsx:apply <other>`', '`the current batch entry`')
  .replaceAll('`/opsx:apply` again', 'the batch apply command again');

export function getBulkApplyInstructions(): string {
  return `Apply multiple active OpenSpec changes sequentially.

The batch applies all active changes by default. When the user supplies change names, apply only those changes, in an order based on implementation dependencies and scope rather than creation dates.

${STORE_SELECTION_GUIDANCE}

${PROJECT_ROOT_GUARD}

**Input**: Optionally specify one or more exact change names. If none are supplied, include all active changes from the selected planning root.

**Steps**

1. **Resolve the batch**

   Run \`openspec list --json\` using the selected root.
   - If no names were supplied, select every active change.
   - If names were supplied, select exactly those names.
   - If a supplied name is missing or duplicated, report it and stop before editing.
   - If there are no selected changes, report that and stop.

2. **Inspect changes and determine the order**

   For every selected change, run \`openspec status --change "<name>" --json\`
   and \`openspec instructions apply --change "<name>" --json\`. Use the
   returned schema, artifact paths, context files, task state, and planning
   scope; do not assume artifact names or paths.

   Read the available scope-defining and implementation-planning artifacts
   and relevant current code and tests. Analyze the entire selected set
   together, identifying dependencies, incompatible assumptions or
   contracts, duplicated work, and opportunities to consolidate or
   redistribute work. Order selected prerequisites before the changes that
   depend on them. For independent changes, choose an order based on their
   scope and the implementation context. Never use creation date as the
   ordering rule.

   If a material dependency or safe order cannot be established from the
   available evidence, explain the uncertainty and ask before editing.

   Keep this analysis read-only. Report the resulting order after preflight
   reconciliation.

3. **Apply the batch's blocked-change policy**

   Determine whether this is a default all-active batch or an explicitly
   named batch; preserve that distinction throughout execution.
   - In an all-active batch, report and skip changes whose apply state is
     blocked, then continue with other applicable changes.
   - In an explicitly named batch, stop when the ordered run reaches a
     blocked change. Do not continue to later entries.
   - Do not start implementation for a blocked change or infer readiness
     from its task count.

4. **Check Git commit readiness**

   Before editing any selected change plan or implementation file, confirm
   this is a Git repository and inspect
   \`git status --short\`, including staged, unstaged, and untracked files.
   If the index already contains staged changes, or there is no Git
   repository, stop before refactoring or implementation. Record
   pre-existing work so it can be excluded from each change's commit. Never
   clean, stash, reset, or discard it.

5. **Preflight and reconcile the applicable batch**

   Use the complete batch analysis from step 2 to prepare the changes that
   the blocked-change policy in step 3 allows this run to process. Analyze
   every selected change, but do not edit a blocked change or process
   entries after the explicit-batch stop point.

   Decide the complete set of plan changes before editing any artifact.
   Automatically reorganize selected plans as needed, without asking for
   approval, when the changes preserve every proposal's initial idea and
   intent:
   - When only some work overlaps, move or consolidate the relevant
     requirements and tasks into the existing change that best owns that
     work. Update affected proposals, specs, designs, and task lists.
     Preserve distinct outcomes and completed task progress.
   - When the selected work forms one coherent outcome, create a new
     change with \`openspec new change "<name>"\`. Use its schema and
     concrete paths from status and artifact instructions to create a
     complete proposal, specs, design, and task list that preserve the
     combined intent. After verifying the survivor's artifacts and
     readiness, delete only the fully absorbed selected source change
     directories using their exact paths. Do not delete unselected changes
     or partially retained changes.
   - Keep independent outcomes as separate changes and order the resulting
     changes by their implementation dependencies and scope.

   If any necessary refactor would change or omit the initial idea or intent
   of a selected proposal, stop before making any part of that refactor.
   Explain which intent cannot be preserved and ask how to proceed. Do not
   ask for approval for intent-preserving moves or merges. Existing blocked
   change, Git safety, and other Apply safeguards still apply.

   After refactoring, rerun status and apply instructions for every
   resulting change. Read the refreshed context files and tasks, confirm
   they are ready under the blocked-change policy, and do not rely on cached
   task state. Show the final ordered changes with a short rationale before
   implementation.

6. **Apply each ordered change in sequence**

   For each applicable change:

   a. Refresh \`openspec status --change "<name>" --json\` and
      \`openspec instructions apply --change "<name>" --json\` when the
      change is reached. If it is now blocked, apply the batch policy in
      step 3.

   b. For the first change, follow the single-change Apply procedure below
      with that exact change name.

   c. Before every later change, compare its existing scope-defining and
      implementation-planning artifacts with all earlier completed changes
      and the resulting code, including relevant tests. Review the current
      change's original proposal or equivalent scope-defining artifact and
      requirements before adapting anything.

      Automatically adapt the current change's implementation and its
      existing implementation-facing planning artifacts, such as design
      and task details, when needed to fit the completed changes and current
      code. Preserve the current change's original proposal scope and
      intended outcome, all its requirements, any earlier completed
      contracts, and completed task progress. Do not rewrite proposals,
      requirement artifacts, or earlier completed changes as part of this
      automatic adaptation. Use concrete artifact paths from current status
      and preserve task checkboxes that are already complete.

      If adaptation would materially change the current proposal's original
      scope or intended outcome, or change externally observable behavior
      or a contract from an earlier completed change, stop before editing
      the plan or code. Explain the divergence or affected contract and ask
      the user how to proceed. Do not start later changes.

      After adapting planning artifacts, rerun status and apply instructions
      for the current change. Read the refreshed context files and tasks
      before implementation; do not rely on cached task state.

      This automatic adaptation applies only to non-breaking integration
      differences caused by earlier completed changes. Other design issues
      still follow the single-change Apply pause-and-ask safeguards below.

   d. Follow the complete single-change Apply procedure below with the
      current change name supplied explicitly. Finish its tasks, sync,
      wiki capture, archive, and commit before starting the next change.
      Keep its own worktree safety, task-progress, and completion rules.

   e. If implementation encounters an error or material ambiguity, stop
      the batch and report completed, skipped, and remaining changes. Do
      not start any later changes. Earlier completed changes remain
      completed; do not attempt rollback.

7. **Report batch results**

   Report the chosen order and rationale, completed changes, blocked
   changes skipped or stopped at, automatic plan reorganizations or
   consolidations, and any remaining work. For a paused batch, explain the
   blocker and wait for guidance.

**Single-change Apply procedure**

For each entry, perform the complete Apply procedure below with that exact
change name as input. The batch order and batch blocked-change policy above
control the sequence; preserve all other single-change Apply safeguards.

${APPLY_ONE_CHANGE}`;
}

export function getBulkApplyChangeSkillTemplate(): SkillTemplate {
  return {
    name: 'openspec-bulk-apply-change',
    description: 'Apply multiple OpenSpec changes sequentially. Use when the user asks to "openspec bulk-apply" or "opsx bulk-apply", or wants several changes applied with dependency-informed ordering.',
    instructions: getBulkApplyInstructions(),
    license: 'MIT',
    compatibility: 'Requires openspec CLI.',
    metadata: { author: 'openspec', version: '1.0' },
  };
}

export function getOpsxBulkApplyCommandTemplate(): CommandTemplate {
  return {
    name: 'OPSX: Bulk Apply',
    description: 'Apply multiple OpenSpec changes sequentially',
    category: 'Workflow',
    tags: ['workflow', 'implementation', 'bulk'],
    content: getBulkApplyInstructions(),
  };
}
